import { getAssetHostForServices } from 'config/api';
import { ImagesService } from 'services';

type CountryResolveResponse = {
  hasError?: boolean;
  data?: { url?: string };
};

const assetHost = getAssetHostForServices();

const buildBrandFallbackCdnUrl = () => {
  return `${assetHost}/brands/placeholder/no-image-available.png`;
};

export const getBrandImagePlaceholderUrl = () => buildBrandFallbackCdnUrl();

const countryImageCache = new Map<string, string>();
const countryImageInFlight = new Map<string, Promise<string | null>>();

export const clearCountryImageCacheForTests = () => {
  countryImageCache.clear();
  countryImageInFlight.clear();
};

const buildCountryImageCacheKey = (countryValue: string, format: string) =>
  `${countryValue.trim().toUpperCase()}-${format}`;

export const getCachedCountryAssetImageUrl = (
  countryValue?: string,
  format = 'icon',
): string | null => {
  const trimmed = countryValue?.trim();
  if (!trimmed) return null;
  return (
    countryImageCache.get(buildCountryImageCacheKey(trimmed, format)) ?? null
  );
};

export const getCountryAssetImageUrl = async (
  countryValue?: string,
  format = 'icon',
): Promise<string | null> => {
  const trimmed = countryValue?.trim();
  if (!trimmed) return null;

  const cacheKey = buildCountryImageCacheKey(trimmed, format);
  const cached = countryImageCache.get(cacheKey);
  if (cached) return cached;

  const inFlight = countryImageInFlight.get(cacheKey);
  if (inFlight !== undefined) return inFlight;

  const promise = ImagesService.getInstance()
    .getCountry({
      name: trimmed,
      format,
    })
    .then((response) => {
      const resolved = response as CountryResolveResponse;
      if (resolved?.hasError || !resolved?.data?.url) return null;
      countryImageCache.set(cacheKey, resolved.data.url);
      return resolved.data.url;
    })
    .finally(() => {
      countryImageInFlight.delete(cacheKey);
    });

  countryImageInFlight.set(cacheKey, promise);
  return promise;
};
